/** What each prop `pattern` in the schema requires, for validation messages. */
export const uiPatternRules: Readonly<Record<string, string>> = {
  "^(?![\\u0000-\\u0020])(?![\\s\\S]*[\\t\\n\\r])(?![a-zA-Z][a-zA-Z0-9+.-]*:)|^(?![\\u0000-\\u0020])(?![\\s\\S]*[\\t\\n\\r])(https?|mailto):":
    "an allowed URL; use a relative path or an http:, https: or mailto: URL, with no leading space or control character and no tab or line break",
  "^[A-Za-z][A-Za-z0-9_:.-]*$":
    "a valid id; start with a letter and use only letters, digits, -, _, : and .",
  "^[A-Za-z][A-Za-z0-9_:.-]*( [A-Za-z][A-Za-z0-9_:.-]*)*$":
    "a list of ids; separate ids with single spaces, each starting with a letter and using only letters, digits, -, _, : and .",
  "^#[0-9a-fA-F]{6}$": "a #rrggbb color such as #3366ff",
  "^(show-modal|close|request-close|show-popover|hide-popover|toggle-popover|--[a-z][a-z0-9-]*)$":
    "a command; use one of show-modal, close, request-close, show-popover, hide-popover, toggle-popover or a custom --name",
};

